"use client";

import { useQuery } from "@tanstack/react-query";
import Link from "next/link";
import { getProducts, getCategories, getTags } from "@/lib/woocommerce";
import { WooProduct, WooCategory, WooTag } from "@/types/product";
import ProductCard from "@/components/ProductCard";
import TagSection from "@/components/TagSection";
import { ArrowRight, ChevronLeft, ChevronRight } from "lucide-react";
import Image from "next/image";
import heroImage from "@/assets/hero-new.png";
import { useRef } from "react";

export default function HomePage() {
    const scrollRef = useRef<HTMLDivElement>(null);

    const { data: products = [], isLoading } = useQuery<WooProduct[]>({
        queryKey: ["products", "featured"],
        queryFn: () => getProducts({ per_page: "10", orderby: "date" }),
    });

    const scroll = (direction: 'left' | 'right') => {
        if (scrollRef.current) {
            const { scrollLeft, clientWidth } = scrollRef.current;
            const scrollTo = direction === 'left' ? scrollLeft - clientWidth : scrollLeft + clientWidth;
            scrollRef.current.scrollTo({ left: scrollTo, behavior: 'smooth' });
        }
    };

    const { data: categories = [] } = useQuery<WooCategory[]>({
        queryKey: ["categories"],
        queryFn: () => getCategories({ hide_empty: "true" }),
    });

    const { data: tags = [] } = useQuery<WooTag[]>({
        queryKey: ["tags"],
        queryFn: () => getTags({ hide_empty: "true" }),
    });

    return (
        <main className="space-y-20 pb-20">
            {/* Hero Full Surface */}
            <section className="relative h-[85vh] md:h-[95vh] w-full flex items-center justify-center overflow-hidden">
                {/* Background Image with 10s Seamless Smooth Zoom Effect */}
                <div className="absolute inset-0 scale-100 animate-[ken-burns_10s_ease-in-out_infinite_alternate]">
                    <Image
                        src={heroImage}
                        alt="Fashion collection background"
                        fill
                        className="object-cover"
                        priority
                    />
                </div>

                {/* Content Overlay */}
                <div className="relative z-10 container mx-auto px-4 text-center space-y-6 md:space-y-10 animate-in fade-in zoom-in duration-1000">
                    <div className="space-y-4">
                        <span className="font-body text-xs md:text-sm font-bold tracking-[0.4em] uppercase text-slate-800/80 block">
                            EXCLUSIVE JEWELRY BOUTIQUE
                        </span>
                        <h1 className="font-display text-4xl md:text-7xl font-bold tracking-tight leading-[1.1] text-slate-900">
                            η ζωή είναι πολύ <span className="text-[#C4196D]">μικρή</span><br />
                            για μέτρια κοσμήματα
                        </h1>
                    </div>

                    <p className="font-body text-lg md:text-xl text-slate-700 max-w-2xl mx-auto leading-relaxed">
                        Ανακαλύψτε τη μοναδική συλλογή μας από κοσμήματα.
                    </p>

                    <div className="flex flex-col sm:flex-row items-center justify-center gap-4 md:gap-8 pt-4">
                        <Link
                            href="/products"
                            className="inline-flex items-center justify-center bg-[#C4196D] text-white px-12 py-5 rounded-full font-body text-sm font-bold tracking-widest hover:scale-105 transition-all shadow-2xl hover:shadow-[#C4196D]/40 min-w-[240px]"
                        >
                            ΔΕΙΤΕ ΤΗ ΣΥΛΛΟΓΗ
                        </Link>
                        <Link
                            href="/products?on_sale=true"
                            className="inline-flex items-center justify-center bg-[#FCF8F8] text-slate-900 px-12 py-5 rounded-full font-body text-sm font-bold tracking-widest hover:scale-105 transition-all shadow-2xl min-w-[240px] border border-slate-100"
                        >
                            SPECIAL OFFERS
                        </Link>
                    </div>
                </div>

                {/* Subtle gradient at the bottom for transition */}
                <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-background/20" />
            </section>

            {/* Categories */}
            {categories.length > 0 && (
                <section className="container mx-auto px-4 md:px-8">
                    <div className="flex flex-col md:flex-row md:items-end justify-between mb-12 gap-4">
                        <div className="space-y-2">
                            <h2 className="font-display text-4xl md:text-5xl font-bold tracking-tight text-[#C4196D]">
                                Εξερευνήστε Κατηγορίες
                            </h2>
                            <p className="text-muted-foreground text-sm font-medium">
                                Βρείτε ακριβώς αυτό που ψάχνετε
                            </p>
                        </div>
                    </div>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                        {categories.filter(c => c.count > 0).slice(0, 4).map((cat) => (
                            <Link
                                key={cat.id}
                                href={`/products?category=${cat.id}`}
                                className="group relative aspect-[4/5] overflow-hidden rounded-3xl bg-secondary shadow-sm hover:shadow-xl transition-all duration-500"
                            >
                                {cat.image && (
                                    <Image
                                        src={cat.image.src}
                                        alt={cat.name}
                                        fill
                                        className="object-cover group-hover:scale-110 transition-transform duration-700 ease-out"
                                        loading="lazy"
                                    />
                                )}
                                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-60 group-hover:opacity-80 transition-opacity" />
                                <div className="absolute bottom-6 left-6 right-6">
                                    <h3 className="font-display text-xl md:text-2xl text-white font-bold tracking-wide" dangerouslySetInnerHTML={{ __html: cat.name }} />
                                    <span className="text-white/60 text-[10px] font-bold tracking-[0.2em] uppercase mt-1 block">
                                        {cat.count} Προϊόντα
                                    </span>
                                </div>
                            </Link>
                        ))}
                    </div>
                </section>
            )}


            {/* Featured Products */}
            <section className="container mx-auto px-4 md:px-8">
                <div className="flex items-center justify-between mb-12">
                    <div className="space-y-2">
                        <h2 className="font-display text-4xl md:text-5xl font-bold tracking-tight text-[#C4196D]">
                            Νέες Αφίξεις
                        </h2>
                        <p className="text-muted-foreground text-sm font-medium">
                            Επιλεγμένα στυλ, μόνο για εσάς
                        </p>
                    </div>
                </div>

                <div className="relative group/carousel">
                    {/* Navigation Arrows */}
                    <button
                        onClick={() => scroll('left')}
                        className="absolute left-0 top-1/2 -translate-y-1/2 -translate-x-1/2 z-10 p-4 rounded-full bg-white/80 backdrop-blur-md border border-slate-200 shadow-xl text-slate-800 opacity-0 group-hover/carousel:opacity-100 transition-all duration-300 hover:bg-[#C4196D] hover:text-white hidden md:flex"
                        aria-label="Scroll left"
                    >
                        <ChevronLeft className="w-6 h-6" />
                    </button>
                    <button
                        onClick={() => scroll('right')}
                        className="absolute right-0 top-1/2 -translate-y-1/2 translate-x-1/2 z-10 p-4 rounded-full bg-white/80 backdrop-blur-md border border-slate-200 shadow-xl text-slate-800 opacity-0 group-hover/carousel:opacity-100 transition-all duration-300 hover:bg-[#C4196D] hover:text-white hidden md:flex"
                        aria-label="Scroll right"
                    >
                        <ChevronRight className="w-6 h-6" />
                    </button>

                {isLoading ? (
                    <div className="flex gap-6 overflow-x-auto pb-4 scrollbar-hide">
                        {Array.from({ length: 10 }).map((_, i) => (
                            <div key={i} className="flex-shrink-0 w-[280px] space-y-4 animate-pulse">
                                <div className="aspect-[3/4] bg-secondary rounded-3xl" />
                                <div className="space-y-2">
                                    <div className="h-5 bg-secondary rounded-full w-3/4" />
                                    <div className="h-4 bg-secondary rounded-full w-1/4" />
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div 
                        ref={scrollRef}
                        className="flex gap-6 overflow-x-auto pb-4 scrollbar-hide scroll-smooth"
                    >
                        {products.map((product: WooProduct) => (
                            <div key={product.id} className="flex-shrink-0 w-[280px]">
                                <ProductCard product={product} />
                            </div>
                        ))}
                    </div>
                )}
                </div>
            </section>
        </main>
    );
}
